<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { readDream, writeDream, dreamOwner, hasLegacyDreamRecords, importLegacyDreamRecords } from '../dream-account'
const route=useRoute(), router=useRouter()
const page=computed(()=>route.path)
// Private records are loaded and saved through the shared authenticated account store.
function read(key,fallback){return readDream(key,fallback)}
const samples=[{id:'sample-sea',title:'海风穿过没有门的房间',motif:'海边',feeling:'温暖',signal:'房间里有海风',date:'2026-10-27',day:'身体舒展 · 情绪松弛',demo:true},{id:'sample-train',title:'停在岔路口的列车',motif:'列车',feeling:'压迫',signal:'一直在等一个决定',date:'2026-10-26',day:'肩颈紧绷 · 压力较高',demo:true},{id:'sample-house',title:'旧屋里的柔光',motif:'旧屋',feeling:'疏离',signal:'有人在叫我',date:'2026-10-25',day:'稍感疲惫 · 心绪平稳',demo:true}]
const snapshots=ref(read('snapshots',[])), seeds=ref(read('seeds',[])), receipts=ref(read('receipts',[])), notes=ref(read('notes',{})), prefs=ref(read('prefs',{motion:true,sound:false,reminder:false}))
const cards=computed(()=>[...snapshots.value,...samples]), toast=ref(''), selected=ref(null), mode=ref('漫游视图'), focus=ref('全部'), chosen=ref([]), clusterName=ref(''), clusters=ref(read('clusters',[]))
let toastTimer, relaxationTimer
function notify(s){toast.value=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3200)}
async function persist(key,value){try{await writeDream(key,value);return true}catch(error){const fields={snapshots,seeds,receipts,notes,prefs,clusters,conversations};if(fields[key])fields[key].value=readDream(key,['notes','prefs','conversations'].includes(key)?{}:[]);notify(error.message||'账号记录未能保存');return false}}
async function saveNote(key,value){notes.value[key]=value;if(!await persist('notes',notes.value))return;notify('你的观察已保存到当前账号')}
const seedType=ref('放下'), seedText=ref(''), signal=ref(''), image=ref(''), feeling=ref({失重:30,压迫:20,温暖:60,疏离:15})
const tonightSeed=computed(()=>seeds.value[0])
const captureSeed=computed(()=>{const date=new Date();date.setDate(date.getDate()-1);return seeds.value.find(s=>s.day===date.toLocaleDateString('sv-SE'))})
async function saveSeed(){if(!seedText.value.trim())return notify('留下一句话，再把种子交给今夜。');seeds.value.unshift({id:Date.now(),day:new Date().toLocaleDateString('sv-SE'),type:seedType.value,text:seedText.value.trim(),date:new Date().toLocaleDateString()});if(!await persist('seeds',seeds.value))return;seedText.value='';notify('今夜的种子已保存到当前账号')}
function upload(e){const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>2*1024*1024)return notify('请选择 2MB 以内的图片');const reader=new FileReader();reader.onload=()=>{image.value=reader.result;imageSource.value='上传画面';imageError.value=''};reader.readAsDataURL(file)}
// Generated images are compressed before local snapshot storage.
const imagePrompt=ref(''), generating=ref(false), imageError=ref(''), imageSource=ref('')
const imageIdeas={海边:'梦里的海边，薄雾漂浮在浅蓝色海面，远处有一座柔光小岛，安静梦幻',列车:'一列穿过淡紫色夜雾的列车，窗外星光流动，柔和梦幻的画面',旧屋:'记忆里的旧屋，窗边洒落温暖光线，空气中漂浮微小光点，宁静柔和'}
function chooseImageIdea(m){representative.value=m;imagePrompt.value=imageIdeas[m];notify('已填入'+m+'画面描述，可继续修改')}
function compressImage(src){return new Promise((resolve,reject)=>{const picture=new Image();picture.onload=()=>{const c=document.createElement('canvas');const scale=Math.min(1,960/Math.max(picture.width,picture.height));c.width=Math.round(picture.width*scale);c.height=Math.round(picture.height*scale);c.getContext('2d').drawImage(picture,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.82))};picture.onerror=()=>reject(new Error('生成图片无法显示，请重新生成。'));picture.src=src})}
async function generateImage(){
 if(generating.value)return
 if(!imagePrompt.value.trim()){imageError.value='先用一句话描述梦里的画面。';return}
 generating.value=true;imageError.value=''
 try{
  const response=await fetch('/api/images/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:imagePrompt.value.trim()})})
  const result=await response.json()
  if(!response.ok)throw new Error(typeof result.detail==='string'?result.detail:'画面生成失败，请稍后重试。')
  image.value=await compressImage(result.image);imageSource.value='AI 生成';notify('梦境画面已生成，可随快照一起保存')
 }catch(error){imageError.value=error.message||'无法连接图像服务，请稍后重试。'}
 finally{generating.value=false}
}
async function saveSnapshot(locked){if(!signal.value.trim()&&!image.value)return notify('留下一幅画面或一个信号，再收下快照。');const now=new Date();const night=new Date(now);night.setDate(night.getDate()-1);const item={id:Date.now(),nightDate:night.toLocaleDateString('sv-SE'),title:signal.value.trim()||representative.value||'一幅醒来的画面',signal:signal.value.trim(),feeling:Object.entries(feeling.value).sort((a,b)=>b[1]-a[1])[0][0],sensations:{...feeling.value},image:image.value,imagePrompt:imageSource.value==='AI 生成'?imagePrompt.value:'',imageSource:imageSource.value,seed:captureSeed.value?.text,date:now.toLocaleDateString('sv-SE'),locked,motif:representative.value||'意识碎片'};snapshots.value.unshift(item);if(await persist('snapshots',snapshots.value)){signal.value='';notify(locked?'重要快照已锁定在当前账号':'快照已保存在当前账号')}}
const corridorCards=computed(()=>cards.value.filter(x=>focus.value==='全部'||x.motif===focus.value).slice().sort((a,b)=>mode.value==='时序视图'?b.date.localeCompare(a.date):a.motif.localeCompare(b.motif)))
const activeSense=ref('')
const senseKeys=['失重','压迫','温暖','疏离']
const senseAngle={失重:-90,压迫:0,温暖:90,疏离:180}
const senseColor=computed(()=>{const f=feeling.value;return `hsl(${255-Math.round(f.温暖*.35)+Math.round(f.压迫*.12)}, ${35+Math.round(f.温暖*.25)}%, ${72-Math.round(f.压迫*.08)}%)`})
const senseScale=computed(()=>1+(feeling.value.温暖+feeling.value.失重*.4)/500)
const senseCaption=computed(()=>{const sorted=Object.entries(feeling.value).sort((a,b)=>b[1]-a[1]);const [a,av]=sorted[0],[b,bv]=sorted[1];return av<35?'昨夜的意识轮廓很轻，仍有许多空白回响。':`昨夜的意识轮廓偏${a}、${bv>45?'带着些'+b:'轻柔地浮动'}`})
function setSense(key,e){const box=e.currentTarget.parentElement.getBoundingClientRect();const x=Math.max(0,Math.min(1,(e.clientX-box.left)/box.width));feeling.value[key]=Math.round(x*100)}
function randomSense(){senseKeys.forEach(k=>feeling.value[k]=Math.floor(18+Math.random()*78));notify('昨夜体感已随机生成')}
const representative=ref(''), forgottenFeel=ref('安稳'), vague=ref('')
async function saveReceipt(){receipts.value.unshift({id:Date.now(),feeling:forgottenFeel.value,note:vague.value,date:new Date().toLocaleDateString()});if(!await persist('receipts',receipts.value))return;vague.value='';notify('空白回执已收好')}
const echoes=computed(()=>receipts.value.filter(r=>snapshots.value.some(s=>s.feeling===r.feeling)))
async function makeCluster(){if(chosen.value.length<2||!clusterName.value.trim())return notify('选取至少两幅快照，并给梦簇起个名字');clusters.value.push({name:clusterName.value,ids:[...chosen.value]});if(!await persist('clusters',clusters.value))return;clusterName.value='';chosen.value=[];notify('梦簇已在当前账号中形成')}
const prompts=['这个体感让你想到白天什么状态？','对比睡前种子，昨夜快照有什么回应？','这个体感以前出现过吗？'], conversations=ref(read('conversations',{}))
async function ask(prompt){if(!selected.value)return notify('先选择一幅意识快照');const s=selected.value;const answer=prompt===prompts[0]?'你留下的体感是“'+s.feeling+'”。白日分身尚未连接，你愿意回想当天身体哪里最有感觉吗？':prompt===prompts[1]?(s.seed?'你曾留下“'+s.seed+'”，快照里的“'+s.signal+'”让你想到什么？两者是否有关，由你来判断。':'这幅快照没有配对的睡前种子，可以从下一晚开始留下一颗。'):'当前账号中有 '+snapshots.value.filter(x=>x.feeling===s.feeling).length+' 幅快照留下相似体感。你觉得它们有什么相似或不同？';(conversations.value[s.id]??=[]).push({q:prompt,a:answer});if(!await persist('conversations',conversations.value))return;notify('示例伴读已回应，尚未连接 AI 服务')}
const dayIndex=ref(Number(route.query.day)||0), dayCard=computed(()=>cards.value[dayIndex.value%cards.value.length]), dayState=ref('疲惫'), duration=ref(3), remaining=ref(0)
const script=computed(()=>dayState.value==='紧绷'?'把注意力带到肩膀。轻轻松开，再慢慢感受双手。':dayState.value==='思绪杂乱'?'让每一个念头像水面上的叶子，不必追赶，慢慢经过。':'找到舒服的姿势。无需用力，让身体被安稳地承托。')
watch(()=>route.query.day,value=>{dayIndex.value=Number(value)||0})
function stopRelax(){clearInterval(relaxationTimer);remaining.value=0;router.push('/dream/cues')}
function relax(){clearInterval(relaxationTimer);remaining.value=duration.value*60;relaxationTimer=setInterval(()=>{remaining.value--;if(remaining.value<=0){clearInterval(relaxationTimer);notify('慢慢回到此刻，给今夜留下一颗种子');router.push('/dream/cues')}},1000)}
function exportData(){const url=URL.createObjectURL(new Blob([JSON.stringify({snapshots:snapshots.value,seeds:seeds.value,receipts:receipts.value,notes:notes.value},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='花屿星-昼夜快照.json';a.click();URL.revokeObjectURL(url);notify('已导出当前账号保存的内容')}
const removed=ref(null)
async function undoRemove(){if(!removed.value)return;snapshots.value.unshift(removed.value);removed.value=null;if(!await persist('snapshots',snapshots.value))return;notify('快照已放回')}
async function bulkLock(){snapshots.value.forEach(s=>s.locked=true);if(!await persist('snapshots',snapshots.value))return;notify('当前账号快照已全部锁定')}
async function remove(s){if(s.locked)return notify('请先解除锁定再删除');removed.value=s;snapshots.value=snapshots.value.filter(x=>x.id!==s.id);if(!await persist('snapshots',snapshots.value))return;notify('已移除此快照')}
const importing=ref(false)
async function importOldRecords(){
 if(importing.value)return
 if(!confirm('这些浏览器旧记录尚未绑定账号。请确认它们属于你，是否导入当前登录账号？原始浏览器记录会保留。'))return
 importing.value=true
 try{await importLegacyDreamRecords();snapshots.value=readDream('snapshots',[]);notify('旧记录已导入当前账号，原始记录已保留')}
 catch(error){notify(error.message||'导入未完成，请稍后重试')}
 finally{importing.value=false}
}
async function toggleLock(s){const next=snapshots.value.map(x=>x.id===s.id?{...x,locked:!x.locked}:x);if(await persist('snapshots',next)){snapshots.value=next;notify(s.locked?'已解除锁定':'已锁定')}}
onBeforeUnmount(()=>{clearTimeout(toastTimer);clearInterval(relaxationTimer)})
</script>

<template>
<div class="signal-pages" :class="{'still':!prefs.motion}">
<p class="prototype-note">{{dreamOwner?'记录保存在当前账号中；标有「示例」的素材仅供体验。':'游客模式：登录后可保存和查看自己的记录。'}}</p>
<template v-if="page==='/capture'">
 <p v-if="captureSeed && prefs.reminder" role="status" class="soft-card">昨夜的种子轻轻浮现：{{captureSeed.text}}</p>
 <section class="soft-card ai-image-card" :aria-busy="generating">
  <h2>画面快照 <span class="ai-badge">AI 生成</span></h2>
  <p>留下一句画面描述，让昨夜的意识碎片慢慢浮现。</p>
  <label for="dream-image-prompt">你梦见了怎样的画面？</label>
  <textarea id="dream-image-prompt" v-model="imagePrompt" maxlength="1000" rows="3" placeholder="例如：漂浮在浅蓝色海面上，远处的小岛亮着温暖的灯…" :disabled="generating" />
  <div class="row"><button v-for="m in ['海边','列车','旧屋']" :key="m" :disabled="generating" @click="chooseImageIdea(m)">{{m}}灵感</button></div>
  <div class="row ai-image-actions"><button class="primary" :disabled="generating" @click="generateImage">{{generating?'正在生成画面…':image?'重新生成画面':'生成梦境画面'}}</button><label class="action">上传已有画面<input type="file" accept="image/*" @change="upload" hidden></label></div>
  <p v-if="generating" role="status">微光正在汇聚，生成可能需要一两分钟…</p>
  <p v-if="imageError" class="image-error" role="alert">{{imageError}}</p>
  <figure v-if="image"><img :src="image" class="snapshot-image" alt="梦境画面预览"><figcaption>{{imageSource||'画面预览'}} · 可随下方快照一起保存</figcaption></figure>
  <div v-else class="ai-image-empty"><span>你的一句话，会成为这幅画面的起点</span></div>
 </section>
 <section class="soft-card sensation-card"><h2>体感快照</h2><p>拖动你的梦境体感，看它们如何组合成昨夜的意识轮廓。</p><div class="energy-dial" :style="{'--orb-color':senseColor,'--orb-scale':senseScale}"><div class="energy-orb"><span>{{Math.round((feeling.失重+feeling.压迫+feeling.温暖+feeling.疏离)/4)}}</span><small>意识能量</small></div><div v-for="key in senseKeys" :key="key" class="energy-track" :class="'track-'+key" @pointermove="activeSense===key&&setSense(key,$event)"><button class="energy-knob" :style="{'--level':feeling[key]}" @pointerdown="activeSense=key" @pointerup="activeSense=''" @pointercancel="activeSense=''" @keydown.left.prevent="feeling[key]=Math.max(0,feeling[key]-5)" @keydown.right.prevent="feeling[key]=Math.min(100,feeling[key]+5)" :aria-label="key+' '+feeling[key]" :aria-valuenow="feeling[key]">{{key}}<b>{{feeling[key]}}</b></button></div></div><p class="sense-caption">{{senseCaption}}</p><button class="random-sense" @click="randomSense">✦ 随机生成昨夜体感</button></section>
 <section class="soft-card"><h2>残留信号</h2><input v-model="signal" maxlength="100" placeholder="一直在跑、房间里有雾，或有人在叫我…"><div class="pair"><div><small>你昨夜埋下的种子</small><p>{{captureSeed?.text||'昨夜没有留下种子，也可以先捕捉快照。'}}</p></div><div><small>你今早捕捉的快照</small><p>{{signal||'等待一缕残留信号'}}</p></div></div><div class="row"><button @click="saveSnapshot(false)">保存为普通快照</button><button class="primary" @click="saveSnapshot(true)">锁定为重要快照</button></div></section>
</template>
<template v-else-if="page==='/dreams'">
 <div class="row"><button v-for="v in ['漫游视图','时序视图']" :key="v" :class="{active:mode===v}" @click="mode=v;notify('已进入'+v)">{{v}}</button><button v-for="m in ['全部','海边','列车','旧屋']" :key="m" :class="{active:focus===m}" @click="focus=m;notify('已聚焦'+m+'快照')">{{m}}</button></div>
 <div class="corridor" :class="{chronological:mode==='时序视图'}"><article v-for="s in corridorCards" :key="s.id" class="soft-card scene"><small>{{s.demo?'示例 · ':''}}{{s.date}}</small><button class="scene-orb" @click="selected=s" :aria-label="'打开'+s.title"></button><h2>{{s.title}}</h2><p>{{s.feeling}} · {{s.motif}}</p><label><input type="checkbox" :value="s.id" v-model="chosen">加入梦簇</label></article></div>
 <section class="soft-card"><h2>让相近的夜晚靠近</h2><div class="row"><input v-model="clusterName" maxlength="24" placeholder="给梦簇一个名字"><button @click="makeCluster">形成梦簇</button></div><button v-for="(c,i) in clusters" :key="i" @click="selected=cards.find(s=>c.ids.includes(s.id));notify(c.name+' · '+c.ids.length+' 幅快照')">{{c.name}} · {{c.ids.length}}</button></section><section v-if="selected" class="soft-card"><h2>{{selected.title}}</h2><p>{{selected.signal}}</p><button @click="selected=null">收起快照</button></section>
</template>
<template v-else-if="page==='/dream/connections'">
 <section class="soft-card"><h2>信号轨迹</h2><p>把反复遇见的画面，与那个白天并排放好。</p><div class="trajectory" v-for="s in cards" :key="s.id"><div class="signal-node"><span></span><strong>{{s.motif}}</strong><small>{{s.demo?'示例 · ':''}}{{s.date}}</small></div><div class="thread" aria-hidden="true"></div><div class="day-signal"><small>{{s.demo?'示例白日状态':'白日分身未连接'}}</small><p>{{s.day||'连接后，可在这里承接当日身体与情绪信号。'}}</p><label>我的信号备注<input :value="notes[s.id]||''" maxlength="140" placeholder="这个画面让我想起…" @change="saveNote(s.id,$event.target.value)"></label></div></div></section>
</template>
<template v-else-if="page==='/dream/cues'">
 <section class="soft-card seed-garden"><h2>种子投放区</h2><div class="row"><button v-for="(desc,type) in {放下:'把白天的一件事留在睡前。',寻找:'希望夜里出现某个画面。',发问:'想问问自己心里的困惑。'}" :key="type" :class="{active:seedType===type}" @click="seedType=type"><strong>{{type}}</strong><small>{{desc}}</small></button></div><input v-model="seedText" maxlength="160" placeholder="一句话就够了，留给夜晚的自己。"><button class="primary" @click="saveSeed">安放今夜种子</button></section><section class="soft-card"><h2>今夜等待区</h2><p>{{tonightSeed?.text||'一片安静的土壤，等待你留下今夜的种子。'}}</p></section><section class="soft-card"><h2>种子与快照的回响</h2><p v-if="!seeds.length">等下一次醒来，让种子与快照相遇。</p><div v-for="s in seeds" :key="s.id" class="pair"><div><small>{{s.date}} · {{s.type}}</small><p>{{s.text}}</p></div><div><small>后续快照</small><p>{{snapshots.find(x=>x.seed===s.text)?.signal||'还在等待夜晚的回响'}}</p></div></div></section>
</template>
<template v-else-if="page==='/ask'">
 <section class="soft-card"><h2>快照伴读区</h2><p>快照翻译员陪你梳理感受，所有联系都由你自己发现。</p><label>选择一幅快照<select @change="selected=cards.find(s=>String(s.id)===$event.target.value)"><option value="">先选择，再一起看看</option><option v-for="s in cards" :key="s.id" :value="s.id">{{s.demo?'示例 · ':''}}{{s.title}}</option></select></label></section><section v-if="selected" class="soft-card"><h2>{{selected.title}}</h2><p>{{selected.signal}} · {{selected.feeling}}</p><small>本地示例伴读，尚未接入 AI 服务。</small><div class="questions"><button v-for="q in prompts" :key="q" @click="ask(q)">{{q}}</button></div><div v-for="(message,i) in conversations[selected.id]||[]" :key="i" class="exchange"><strong>{{message.q}}</strong><p>{{message.a}}</p></div></section><div v-else class="quiet">先靠近一幅快照，谈话才有安放的地方。</div>
</template>
<template v-else-if="page==='/dream/relax'">
 <section class="soft-card"><h2>昼夜卸荷通道</h2><p>白日分身尚未连接，你可以先选择此刻状态。</p><div class="row"><button v-for="s in ['紧绷','思绪杂乱','疲惫']" :key="s" :class="{active:dayState===s}" @click="dayState=s">{{s}}</button></div><label>留给自己几分钟<input type="number" v-model.number="duration" min="1" max="30"></label><div class="breathing" :class="{running:remaining>0}"><span>{{remaining>0?Math.ceil(remaining/60)+' 分钟':'慢慢安顿'}}</span></div><p class="guidance">{{script}}</p><div class="row"><button @click="duration=Math.max(1,Math.min(30,Number(duration)||3));relax()">{{remaining?'重新开始':'开始卸荷'}}</button><button @click="stopRelax()">结束，种下今夜种子</button></div></section>
</template>
<template v-else-if="page==='/dream/emotions'">
 <section class="soft-card"><h2>情绪共振波纹</h2><p>示例波纹 · 上层白日情绪，下层夜间体感。同步或错位，都只是值得留意的个人感受。</p><div class="ripples"><svg viewBox="0 0 800 240" preserveAspectRatio="none" aria-hidden="true"><path d="M0 65 C70 10 130 120 200 65S330 10 400 65S530 120 600 65S730 10 800 65"/><path d="M0 180 C70 230 130 130 200 180S330 230 400 180S530 130 600 180S730 230 800 180"/></svg><div class="ripple-points"><button v-for="(s,i) in cards" :key="s.id" @click="router.push({path:'/dream/day-night',query:{day:i}})">{{s.date}}<small>{{s.feeling}}</small></button></div></div></section>
</template>
<template v-else-if="page==='/dream/day-night'">
 <section class="soft-card"><div class="row"><h2>昼夜映射实验室</h2><button @click="dayIndex=(dayIndex+cards.length-1)%cards.length">前一幅</button><button @click="dayIndex=(dayIndex+1)%cards.length">后一幅</button></div><small>{{dayCard.date}} · {{dayCard.demo?'示例映射':'白日信号等待连接'}}</small><div class="pair"><div><h3>当日安康分身数据</h3><p>{{dayCard.day||'尚未连接安康守护，暂不展示白日身体信号。'}}</p></div><div><h3>当夜意识快照</h3><p>{{dayCard.title}}</p><p>{{dayCard.signal}} · {{dayCard.feeling}}</p></div></div><label>我的观察笔记<textarea rows="2" maxlength="300" :value="notes['day-'+dayCard.id]||''" placeholder="只有你自己发现的联系，才值得留在这里。" @change="saveNote('day-'+dayCard.id,$event.target.value)"></textarea></label><div class="row"><button v-for="(s,i) in cards" :key="s.id" @click="dayIndex=i">{{s.date}}</button></div></section>
</template>
<template v-else-if="page==='/dream/forgotten'">
 <section class="soft-card"><div class="blank-receipt" aria-hidden="true"></div><h2>空白回执</h2><p>不必追回情节，收下醒来的那一刻。</p><div class="row"><button v-for="f in ['心慌','安稳','沉闷','失重','怅然']" :key="f" :class="{active:forgottenFeel===f}" @click="forgottenFeel=f">{{f}}</button></div><input v-model="vague" maxlength="100" placeholder="一句模糊感受，也可以不写。"><button class="primary" @click="saveReceipt">收下空白回执</button></section><section class="soft-card"><h2>模糊记忆库</h2><p v-if="!receipts.length">梦不见了，醒来的感受仍有地方停留。</p><p v-if="echoes.length">这个感受，你曾经在一场遗忘的梦里出现过。</p><div v-for="r in receipts" :key="r.id" class="receipt"><small>{{r.date}}</small><strong>{{r.feeling}}</strong><p>{{r.note||'没有文字，只有一份感受。'}}</p></div></section>
</template>
<template v-else-if="page==='/dream/space'">
 <section class="soft-card"><h2>分身同步</h2><p>安康、花屿星与心灵共用一个账号。梦境记录独立保存，健康记录不会自动成为梦境快照。</p><button @click="notify(dreamOwner?'当前已使用共享账号，梦境记录保存在此账号中':'当前为游客模式，请先登录账号')">了解绑定状态</button></section><section class="soft-card"><h2>快照管理</h2><button v-if="dreamOwner && hasLegacyDreamRecords()" :disabled="importing" @click="importOldRecords">{{importing?'正在导入…':'导入此浏览器的旧记录'}}</button><button @click="bulkLock">锁定所有快照</button> <button v-if="removed" @click="undoRemove">撤回刚才的删除</button> <button @click="exportData">导出当前账号快照</button><p v-if="!snapshots.length">还没有自己的快照，示例素材不会混入导出文件。</p><div v-for="s in snapshots" :key="s.id" class="row"><span>{{s.title}}</span><button @click="toggleLock(s)">{{s.locked?'解除锁定':'锁定'}}</button><button @click="remove(s)">删除</button></div></section><section class="soft-card"><h2>体验偏好</h2><label><input type="checkbox" v-model="prefs.motion" @change="persist('prefs',prefs)">柔和波纹动画</label><label><input type="checkbox" v-model="prefs.reminder" @change="persist('prefs',prefs)">进入记梦时浮现种子</label><p>提醒仅在页面内呈现，不发送后台通知。音效服务尚未接通。</p><h2>隐私说明</h2><p>快照、种子与回执保存在当前登录账号中。退出后不显示个人记录，再次登录可继续查看。</p></section>
</template>
<div class="signal-toast" role="status" aria-live="polite">{{toast}}</div>
</div>
</template>

